import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../services/profile_service.dart';
import 'orders_screen.dart';
class ProfileScreen extends StatelessWidget { const ProfileScreen({super.key}); @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Profile')),body:StreamBuilder(stream:ProfileService().profile(),builder:(c,s){final m=s.data?.data()??{};return ListView(children:[UserAccountsDrawerHeader(currentAccountPicture:const CircleAvatar(child:Icon(Icons.person)),accountName:Text(m['name']??'FreshCart user'),accountEmail:Text(m['email']??m['phone']??'')),ListTile(leading:const Icon(Icons.receipt_long),title:const Text('My Orders'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const OrdersScreen()))),const ListTile(leading:Icon(Icons.location_on),title:Text('Saved Addresses')),const ListTile(leading:Icon(Icons.favorite_border),title:Text('Wishlist')),const ListTile(leading:Icon(Icons.local_offer_outlined),title:Text('Offers & Coupons')),const ListTile(leading:Icon(Icons.notifications_none),title:Text('Notifications')),const ListTile(leading:Icon(Icons.help_outline),title:Text('Help & Support')),ListTile(leading:const Icon(Icons.logout),title:const Text('Logout'),onTap:()async{await FirebaseAuth.instance.signOut();if(c.mounted)Navigator.pushNamedAndRemoveUntil(c,'/login',(_)=>false);})]);})); }
